// Frozen fixtures generated by actual Materializer at
// 865e5a5541e72b397b3e6cb58e9cde0bff6dc690. Slot1 creates t(id INTEGER PRIMARY KEY).
// Slot2 inserts42 then CREATE TABLE aux(x INTEGER) ExpectedRowsAffected=0:
// the old engine rejects the whole command; the unfenced repaired engine commits.
func TestLegacyPolicyCannotOpenOrReplay(t *testing.T) {
	ctx := context.Background()
	legacy, err := os.ReadFile("testdata/sql-policy-legacy/slot2.bin")
	if err != nil {
		t.Fatal(err)
	}
	for _, name := range []string{"slot1.db", "slot2.db"} {
		t.Run(name, func(t *testing.T) {
			original, err := os.ReadFile(filepath.Join("testdata/sql-policy-legacy", name))
			if err != nil {
				t.Fatal(err)
			}
			target := filepath.Join(t.TempDir(), name)
			if err = os.WriteFile(target, original, 0600); err != nil {
				t.Fatal(err)
			}
			if m, err := Open(target, 1); !errors.Is(err, sqlpolicy.ErrIncompatible) {
				if m != nil {
					m.Close()
				}
				t.Fatalf("open: %v", err)
			}
			after, err := os.ReadFile(target)
			if err != nil || !bytes.Equal(original, after) {
				t.Fatal("legacy database modified", err)
			}
		})
	}
	m, err := Open(filepath.Join(t.TempDir(), "new.db"), 1)
	if err != nil {
		t.Fatal(err)
	}
	defer m.Close()
	good := policySQL(t, "CREATE TABLE fresh(id INTEGER)")
	if err = m.Apply(ctx, 1, good); err != nil {
		t.Fatal(err)
	}
	for _, slot := range []uint64{0, 1, 2} {
		if err = m.Apply(ctx, slot, legacy); !errors.Is(err, sqlpolicy.ErrIncompatible) {
			t.Fatalf("slot%d: %v", slot, err)
		}
	}
	if err = m.ValidateTip(1, legacy); !errors.Is(err, sqlpolicy.ErrIncompatible) {
		t.Fatal(err)
	}
	page := []quepaxa.DecidedValue{{Slot: 2, Value: policySQL(t, "INSERT INTO fresh VALUES(1)")}, {Slot: 3, Value: legacy}}
	if err = m.ApplyBatch(ctx, page); !errors.Is(err, sqlpolicy.ErrIncompatible) {
		t.Fatal(err)
	}
	if m.Tip() != 1 {
		t.Fatal("advanced incompatible page")
	}
	rows, err := m.Query(ctx, "SELECT COUNT(*) FROM fresh")
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	var count int
	rows.Next()
	if err = rows.Scan(&count); err != nil || count != 0 {
		t.Fatal(count, err)
	}
	rows.Close()
	if _, found, err := m.MutationReceipt(ctx, types.MutationSQL, "ddl-guard"); err != nil || found {
		t.Fatal("manufactured receipt", err)
	}
}

func TestApplyBatchValidatesAllSQLBeforeApplying(t *testing.T) {
	ctx := context.Background()
	m, err := Open(filepath.Join(t.TempDir(), "batch.db"), 1)
	if err != nil {
		t.Fatal(err)
	}
	defer m.Close()
	good := policySQL(t, "CREATE TABLE safe(id INTEGER)")
	malformed := append(append([]byte(nil), good...), []byte(" true")...)
	for _, badSlot := range []quepaxa.Slot{0, 2} {
		page := []quepaxa.DecidedValue{{Slot: 1, Value: good}, {Slot: badSlot, Value: malformed}}
		if err := m.ApplyBatch(ctx, page); err == nil {
			t.Fatalf("slot %d: accepted trailing JSON", badSlot)
		}
		if m.Tip() != 0 {
			t.Fatalf("slot %d: advanced tip to %d", badSlot, m.Tip())
		}
	}
	if err := m.Apply(ctx, 1, good); err != nil {
		t.Fatal(err)
	}
}

func TestApplyBatchRetainedSQLLimits(t *testing.T) {
	ctx := context.Background()
	m, err := Open(filepath.Join(t.TempDir(), "batch.db"), 1)
	if err != nil {
		t.Fatal(err)
	}
	defer m.Close()
	page := []quepaxa.DecidedValue{{Slot: 1, Value: policySQL(t, "CREATE TABLE cache_test(id INTEGER)")}, {Slot: 2, Value: types.EncodeReadBarrier([types.ReadBarrierNonceSize]byte{})}}
	for i := 0; i < maxRetainedSQLBatches; i++ {
		value, err := types.EncodeSQLBatch([]types.SQLCommand{{RequestID: fmt.Sprint(i), SQL: "INSERT INTO cache_test VALUES (1)"}})
		if err != nil {
			t.Fatal(err)
		}
		page = append(page, quepaxa.DecidedValue{Slot: quepaxa.Slot(len(page) + 1), Value: value})
	}
	retained, err := m.validateBatchPolicy(page)
	if err != nil || len(retained) != maxRetainedSQLBatches || retained[len(page)-1] != nil || retained[1] != nil {
		t.Fatalf("retained=%d last=%v barrier=%v err=%v", len(retained), retained[len(page)-1] != nil, retained[1] != nil, err)
	}
	bad := append(append([]byte(nil), page[len(page)-1].Value...), []byte(" true")...)
	invalid := append(append([]quepaxa.DecidedValue(nil), page...), quepaxa.DecidedValue{Slot: quepaxa.Slot(len(page) + 1), Value: bad})
	if err := m.ApplyBatch(ctx, invalid); err == nil || m.Tip() != 0 {
		t.Fatalf("malformed beyond limit: tip=%d err=%v", m.Tip(), err)
	}
	if err := m.ApplyBatch(ctx, page); err != nil {
		t.Fatal(err)
	}
	retained, err = m.validateBatchPolicy(page)
	if err != nil || len(retained) != 0 {
		t.Fatalf("replay retained=%d err=%v", len(retained), err)
	}
	if err := m.ApplyBatch(ctx, page); err != nil {
		t.Fatal(err)
	}
	var count int
	if err := m.queryRow(ctx, "SELECT COUNT(*) FROM cache_test").Scan(&count); err != nil || count != maxRetainedSQLBatches || m.Tip() != uint64(len(page)) {
		t.Fatalf("count=%d tip=%d err=%v", count, m.Tip(), err)
	}
	large, err := types.EncodeSQLBatch([]types.SQLCommand{{SQL: "SELECT 1 /*" + strings.Repeat("x", maxRetainedSQLSourceBytes) + "*/"}})
	if err != nil {
		t.Fatal(err)
	}
	retained, err = m.validateBatchPolicy([]quepaxa.DecidedValue{{Slot: 1000, Value: large}, {Slot: 1001, Value: page[0].Value}})
	if err != nil || len(retained) != 1 || retained[0] != nil || retained[1] == nil {
		t.Fatalf("byte cap: retained=%d err=%v", len(retained), err)
	}
	medium, err := types.EncodeSQLBatch([]types.SQLCommand{{SQL: "SELECT 1 /*" + strings.Repeat("x", maxRetainedSQLSourceBytes/2) + "*/"}})
	if err != nil {
		t.Fatal(err)
	}
	retained, err = m.validateBatchPolicy([]quepaxa.DecidedValue{{Slot: 1000, Value: medium}, {Slot: 1001, Value: medium}})
	if err != nil || len(retained) != 1 || retained[0] == nil || retained[1] != nil {
		t.Fatalf("cumulative byte cap: retained=%d err=%v", len(retained), err)
	}
	fixture, err := types.EncodeSQLBatch([]types.SQLCommand{{SQL: "SELECT 1 /*" + strings.Repeat("x", 20<<10) + "*/"}})
	if err != nil {
		t.Fatal(err)
	}
	largePage := make([]quepaxa.DecidedValue, 7)
	for i := range largePage {
		largePage[i] = quepaxa.DecidedValue{Slot: quepaxa.Slot(1000 + i), Value: fixture}
	}
	retained, err = m.validateBatchPolicy(largePage)
	if err != nil || len(retained) != 6 || retained[5] == nil || retained[6] != nil {
		t.Fatalf("large page byte cap: retained=%d err=%v", len(retained), err)
	}
	badLarge := append(append([]byte(nil), fixture...), []byte(" true")...)
	largePage = append(largePage, quepaxa.DecidedValue{Slot: 1007, Value: badLarge})
	tip := m.Tip()
	if err := m.ApplyBatch(ctx, largePage); err == nil || !strings.Contains(err.Error(), "trailing JSON") || m.Tip() != tip {
		t.Fatalf("malformed beyond byte limit: tip=%d err=%v", m.Tip(), err)
	}
}

func TestApplyBatchSQLRetentionByteBoundary(t *testing.T) {
	for _, extra := range []int{0, 1} {
		t.Run(fmt.Sprintf("bytes-%d", maxRetainedSQLSourceBytes+extra), func(t *testing.T) {
			ctx := context.Background()
			m, err := Open(filepath.Join(t.TempDir(), "batch.db"), 1)
			if err != nil {
				t.Fatal(err)
			}
			defer m.Close()
			if err := m.Apply(ctx, 1, policySQL(t, "CREATE TABLE byte_boundary(id INTEGER)")); err != nil {
				t.Fatal(err)
			}
			page := make([]quepaxa.DecidedValue, 2)
			for i := range page {
				value, err := types.EncodeSQLBatch([]types.SQLCommand{{RequestID: fmt.Sprint(i), SQL: "INSERT INTO byte_boundary VALUES (1)"}})
				if err != nil {
					t.Fatal(err)
				}
				size := maxRetainedSQLSourceBytes / 2
				if i == 1 {
					size += extra
				}
				if len(value) > size {
					t.Fatalf("encoded SQL size %d exceeds fixture size %d", len(value), size)
				}
				value = append(value, bytes.Repeat([]byte(" "), size-len(value))...)
				page[i] = quepaxa.DecidedValue{Slot: quepaxa.Slot(i + 2), Value: value}
			}
			if size := len(page[0].Value) + len(page[1].Value); size != maxRetainedSQLSourceBytes+extra {
				t.Fatalf("page bytes=%d", size)
			}
			retained, err := m.validateBatchPolicy(page)
			if err != nil || retained[0] == nil || (retained[1] != nil) != (extra == 0) {
				t.Fatalf("retained=%d second=%v err=%v", len(retained), retained[1] != nil, err)
			}
			if err := m.ApplyBatch(ctx, page); err != nil {
				t.Fatal(err)
			}
			var count int
			if err := m.queryRow(ctx, "SELECT COUNT(*) FROM byte_boundary").Scan(&count); err != nil || count != 2 || m.Tip() != 3 {
				t.Fatalf("count=%d tip=%d err=%v", count, m.Tip(), err)
			}
		})
	}
}

func TestBatchPolicyTipHintDoesNotBlockOrSkipValidation(t *testing.T) {
	m, err := Open(filepath.Join(t.TempDir(), "batch.db"), 1)
	if err != nil {
		t.Fatal(err)
	}
	defer m.Close()
	value := policySQL(t, "CREATE TABLE hint_test(id INTEGER)")
	if err := m.Apply(context.Background(), 1, value); err != nil {
		t.Fatal(err)
	}
	page := []quepaxa.DecidedValue{{Slot: 1, Value: value}, {Slot: 2, Value: value}}
	retained, err := m.validateBatchPolicy(page)
	if err != nil || retained[0] != nil || retained[1] == nil {
		t.Fatalf("mixed replay: retained=%v err=%v", retained, err)
	}
	bad := append(append([]byte(nil), value...), []byte(" true")...)
	if _, err := m.validateBatchPolicy([]quepaxa.DecidedValue{{Slot: 1, Value: bad}}); err == nil {
		t.Fatal("skipped validation for replayed slot")
	}
	m.mu.Lock()
	done := make(chan map[int][]types.SQLCommand, 1)
	go func() {
		retained, _ := m.validateBatchPolicy(page)
		done <- retained
	}()
	select {
	case retained = <-done:
		m.mu.Unlock()
		if retained[0] == nil || retained[1] == nil {
			t.Fatal("contended hint did not fall back to retention")
		}
	case <-time.After(5 * time.Second):
		m.mu.Unlock()
		<-done
		t.Fatal("preflight blocked on tip hint")
	}
}

func TestLegacySnapshotRefusalPreservesLiveState(t *testing.T) {
	ctx := context.Background()
	m, err := Open(filepath.Join(t.TempDir(), "current.db"), 1)
	if err != nil {
		t.Fatal(err)
	}
	defer m.Close()
	if err = m.Apply(ctx, 1, policySQL(t, "CREATE TABLE current_state(id INTEGER)")); err != nil {
		t.Fatal(err)
	}
	if err = m.RestoreCheckpoint(ctx, []CheckpointFile{{Role: CheckpointSQLite, Path: "testdata/sql-policy-legacy/slot2.db"}, {Role: CheckpointGraphData, Path: "not-installed"}}); !errors.Is(err, sqlpolicy.ErrIncompatible) {
		t.Fatalf("restore: %v", err)
	}
	if m.Tip() != 1 {
		t.Fatal("restore changed tip")
	}
	if err = m.Apply(ctx, 2, policySQL(t, "INSERT INTO current_state VALUES(7)")); err != nil {
		t.Fatal(err)
	}
}

func TestMaterializationPolicyMarkerIsRequired(t *testing.T) {
	for _, marker := range []string{"", "1", "2", "3", "4", "5", "not-a-version"} {
		t.Run(marker, func(t *testing.T) {
			path := filepath.Join(t.TempDir(), "state.db")
			m, err := Open(path, 1)
			if err != nil {
				t.Fatal(err)
			}
			if marker == "" {
				_, err = m.db.Exec(`DELETE FROM _rhiza_meta WHERE key='sql_execution_policy'`)
			} else {
				_, err = m.db.Exec(`UPDATE _rhiza_meta SET value=? WHERE key='sql_execution_policy'`, marker)
			}
			if err != nil {
				t.Fatal(err)
			}
			m.Close()
			if other, err := Open(path, 1); !errors.Is(err, sqlpolicy.ErrIncompatible) {
				if other != nil {
					other.Close()
				}
				t.Fatal(err)
			}
		})
	}
}

// These are actual policy-1 artifacts made at dd6a153, not relabeled current data.
func TestPolicyOneArtifactsAreNotReinterpreted(t *testing.T) {
	ctx := context.Background()
	for _, name := range []string{"ordinary", "temp"} {
		t.Run(name, func(t *testing.T) {
			oldPath := filepath.Join("testdata/sql-policy-1", name+".db")
			before, err := os.ReadFile(oldPath)
			if err != nil {
				t.Fatal(err)
			}
			target := filepath.Join(t.TempDir(), "old.db")
			if err = os.WriteFile(target, before, 0600); err != nil {
				t.Fatal(err)
			}
			if m, err := Open(target, 1); !errors.Is(err, sqlpolicy.ErrIncompatible) {
				if m != nil {
					m.Close()
				}
				t.Fatalf("open=%v", err)
			}
			after, err := os.ReadFile(target)
			if err != nil || !bytes.Equal(before, after) {
				t.Fatal("changed legacy data", err)
			}
			value, err := os.ReadFile(filepath.Join("testdata/sql-policy-1", name+".bin"))
			if err != nil {
				t.Fatal(err)
			}
			m, err := Open(filepath.Join(t.TempDir(), "new.db"), 1)
			if err != nil {
				t.Fatal(err)
			}
			defer m.Close()
			if err = m.Apply(ctx, 1, policySQL(t, "CREATE TABLE sentinel(id INTEGER)")); err != nil {
				t.Fatal(err)
			}
			for _, slot := range []uint64{0, 1, 2} {
				if err = m.Apply(ctx, slot, value); !errors.Is(err, sqlpolicy.ErrIncompatible) {
					t.Fatalf("apply slot%d=%v", slot, err)
				}
			}
			if err = m.ValidateTip(1, value); !errors.Is(err, sqlpolicy.ErrIncompatible) {
				t.Fatal(err)
			}
			if err = m.ApplyBatch(ctx, []quepaxa.DecidedValue{{Slot: 2, Value: policySQL(t, "INSERT INTO sentinel VALUES(1)")}, {Slot: 3, Value: value}}); !errors.Is(err, sqlpolicy.ErrIncompatible) {
				t.Fatal(err)
			}
			if m.Tip() != 1 {
				t.Fatal("legacy page advanced tip")
			}
			if err = m.RestoreCheckpoint(ctx, []CheckpointFile{{Role: CheckpointSQLite, Path: target}, {Role: CheckpointGraphData, Path: "not-installed"}}); !errors.Is(err, sqlpolicy.ErrIncompatible) {
				t.Fatal(err)
			}
			result, err := m.QueryResult(ctx, "SELECT COUNT(*) FROM sentinel", nil)
			if err != nil || result.Rows[0][0] != int64(0) {
				t.Fatalf("result=%+v err=%v", result, err)
			}
		})
	}
}

// Actual policy-2 artifacts generated at f3372dd using Materializer.Apply.
// The maximum-rowid command committed under policy 2 and rejects under policy 3.
func TestPolicyTwoMaxRowIDArtifactsAreNotReinterpreted(t *testing.T) {
	checkHistoricalSQLArtifacts(t, "testdata/sql-policy-2/max-rowid", "2", "SELECT max(id) FROM items", int64(9223372036854775807))
}

// Produced by the policy-3 Materializer at 4056e67, not a relabeled current DB.
func TestPolicyThreePragmaArtifactsAreNotReinterpreted(t *testing.T) {
	checkHistoricalSQLArtifacts(t, "testdata/sql-policy-3/pragma", "3", "SELECT value FROM probe", "/private/tmp/rhiza-policy3-pragma-fixture-v2/state.db")
}

func checkHistoricalSQLArtifacts(t *testing.T, prefix, expectedMarker, query string, expected any) {
	t.Helper()
	ctx := context.Background()
	oldPath := prefix + ".db"
	oldDB, err := driver.Open("file:" + oldPath + "?mode=ro")
	if err != nil {
		t.Fatal(err)
	}
	var marker string
	var observed any
	if err = oldDB.QueryRow(`SELECT value FROM _rhiza_meta WHERE key='sql_execution_policy'`).Scan(&marker); err != nil || marker != expectedMarker {
		t.Fatal(marker, err)
	}
	if err = oldDB.QueryRow(query).Scan(&observed); err != nil || observed != expected {
		t.Fatal(observed, err)
	}
	if err = oldDB.Close(); err != nil {
		t.Fatal(err)
	}
	before, err := os.ReadFile(oldPath)
	if err != nil {
		t.Fatal(err)
	}
	target := filepath.Join(t.TempDir(), "old.db")
	if err = os.WriteFile(target, before, 0600); err != nil {
		t.Fatal(err)
	}
	if m, e := Open(target, 1); !errors.Is(e, sqlpolicy.ErrIncompatible) {
		if m != nil {
			m.Close()
		}
		t.Fatal(e)
	}
	after, err := os.ReadFile(target)
	if err != nil || !bytes.Equal(before, after) {
		t.Fatal("modified old state", err)
	}
	old, err := os.ReadFile(prefix + ".bin")
	if err != nil {
		t.Fatal(err)
	}
	m, err := Open(filepath.Join(t.TempDir(), "new.db"), 1)
	if err != nil {
		t.Fatal(err)
	}
	defer m.Close()
	if err = m.Apply(ctx, 1, policySQL(t, "CREATE TABLE sentinel(id INTEGER)")); err != nil {
		t.Fatal(err)
	}
	for _, slot := range []uint64{0, 1, 2} {
		if err = m.Apply(ctx, slot, old); !errors.Is(err, sqlpolicy.ErrIncompatible) {
			t.Fatalf("slot%d %v", slot, err)
		}
	}
	if err = m.ValidateTip(1, old); !errors.Is(err, sqlpolicy.ErrIncompatible) {
		t.Fatal(err)
	}
	if err = m.ApplyBatch(ctx, []quepaxa.DecidedValue{{Slot: 2, Value: policySQL(t, "INSERT INTO sentinel VALUES(1)")}, {Slot: 3, Value: old}}); !errors.Is(err, sqlpolicy.ErrIncompatible) {
		t.Fatal(err)
	}
	if m.Tip() != 1 {
		t.Fatal("advanced tip")
	}
	if err = m.RestoreCheckpoint(ctx, []CheckpointFile{{Role: CheckpointSQLite, Path: target}, {Role: CheckpointGraphData, Path: "must-not-install"}}); !errors.Is(err, sqlpolicy.ErrIncompatible) {
		t.Fatal(err)
	}
	rows, err := m.QueryResult(ctx, "SELECT COUNT(*) FROM sentinel", nil)
	if err != nil || rows.Rows[0][0] != int64(0) {
		t.Fatal(rows, err)
	}
}
